#!/usr/bin/env bash
# SPDX-License-Identifier: MIT
# /*!
# ****************************
# \file       format_cxx.sh
# \brief      Format the C sources with clang-format.
#
# \author     Z. BEN-AKKA
# \version    1.0
# \date       10/10/2026
#
# \details
#   Formats every .c and .h under dev/ and boards/, each with the nearest
#   .clang-format (dev/.clang-format, boards/<board>/.clang-format).
#   Generated files, marked "Generated by" in their header, are
#   left as their generator wrote them.
#
#     dev/scripts/format_cxx.sh           format in place
#     dev/scripts/format_cxx.sh --check   only report, fail if anything would change
#
#   Run from the repository root (make format does).
#
# \section format_cxx_sh_version_history Version history
# | Version | Date       | Author      | Description      |
# |:-------:|:----------:|:------------|:-----------------|
# | 1.0     | 10/10/2026 | Z. BEN-AKKA | Initial version. |
# ****************************
# */

set -euo pipefail

CLANG_FORMAT="${CLANG_FORMAT:-clang-format}"

if ! command -v "$CLANG_FORMAT" >/dev/null 2>&1; then
  echo "format_cxx.sh: $CLANG_FORMAT not found (sudo apt install clang-format)" >&2
  exit 1
fi

mode=(-i)
done_msg="formatted"
if [[ "${1:-}" == "--check" ]]; then
  mode=(--dry-run --Werror)
  done_msg="checked"
fi

files=()
while IFS= read -r -d '' f; do
  if ! head -n 10 "$f" | grep -q "Generated by"; then
    files+=("$f")
  fi
done < <(find dev boards -type f \( -name '*.c' -o -name '*.h' \) -print0 | sort -z)

"$CLANG_FORMAT" --style=file "${mode[@]}" "${files[@]}"
echo "format_cxx.sh: ${#files[@]} files $done_msg"
